def pick(v,lang):
    if isinstance(v,dict):
        if set(v.keys()).issubset({'ru','en'}) and lang in v:return pick(v[lang],lang)
        return {k:pick(val,lang) for k,val in v.items()}
    if isinstance(v,list):return [pick(x,lang) for x in v]
    return v

def upsert_events(path,lang):
    payload=json.loads(path.read_text(encoding='utf-8'))
    old={e['id']:e for e in payload['events']}
    for raw in EVENTS: old[raw['id']]=pick(raw,lang)
    if 'acs-2026' in old: old['acs-2026']['region']='Китай / Greater China' if lang=='ru' else 'China / Greater China'
    payload['events']=sorted(old.values(),key=lambda e:(e['start'],e['id']))
    payload['verifiedAt']=VERIFIED
    payload['generatedAt']=datetime.now(timezone.utc).isoformat(timespec='seconds')
    path.write_text(json.dumps(payload,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    return set(old)

ru_ids=upsert_events(DATA/'ophthalmology-events.ru.json','ru')
en_ids=upsert_events(DATA/'ophthalmology-events.en.json','en')
assert ru_ids==en_ids

