REGIONS_RU=[('all','Все'),('Россия','Россия'),('СНГ','СНГ'),('Европа','Европа'),('Китай / Greater China','Китай / Greater China'),('Азия–Тихоокеанский','Азия–Тихоокеанский'),('Ближний Восток','Ближний Восток'),('Африка','Африка'),('Северная Америка','Северная Америка'),('Латинская Америка','Латинская Америка')]
REGIONS_EN=[('all','All'),('Russia','Russia'),('CIS','CIS'),('Europe','Europe'),('China / Greater China','China / Greater China'),('Asia–Pacific','Asia–Pacific'),('Middle East','Middle East'),('Africa','Africa'),('North America','North America'),('Latin America','Latin America')]
SPECS_RU=[('all','Все'),('Катаракта / ИОЛ','Катаракта / ИОЛ'),('Рефракция','Рефракция'),('Роговица','Роговица'),('Retina','Retina'),('Глаукома','Глаукома'),('Воспаление','Воспаление'),('Детская офтальмология','Детская офтальмология'),('Страбизм','Страбизм'),('Нейроофтальмология','Нейроофтальмология'),('Окулопластика','Окулопластика'),('Research','Research'),('AI / управление','AI / управление')]
SPECS_EN=[('all','All'),('Cataract / IOL','Cataract / IOL'),('Refractive','Refractive'),('Cornea','Cornea'),('Retina','Retina'),('Glaucoma','Glaucoma'),('Inflammation','Inflammation'),('Pediatric ophthalmology','Pediatric ophthalmology'),('Strabismus','Strabismus'),('Neuro-ophthalmology','Neuro-ophthalmology'),('Oculoplastics','Oculoplastics'),('Research','Research'),('AI / management','AI / management')]

def buttons(items,attr):
    return ''.join(f'<button class="filter-chip{" active" if key=="all" else ""}" type="button" data-{attr}="{key}">{label}</button>' for key,label in items)

def patch_page(path,lang):
    s=path.read_text(encoding='utf-8')
    regs=REGIONS_RU if lang=='ru' else REGIONS_EN
    specs=SPECS_RU if lang=='ru' else SPECS_EN
    s=re.sub(r'(<div class="filter-scroll" id="region-filters"[^>]*>).*?(</div></div><div class="filter-block">)',lambda m:m.group(1)+buttons(regs,'region')+m.group(2),s,count=1)
    s=re.sub(r'(<div class="filter-scroll" id="specialty-filters"[^>]*>).*?(</div></div><div class="toggles">)',lambda m:m.group(1)+buttons(specs,'specialty')+m.group(2),s,count=1)
    s=re.sub(r'<p class="hero-note">.*?</p>','',s,count=1)
    if lang=='ru':
        s=s.replace('Профессиональный календарь · Россия · СНГ · Азия–Тихоокеанский регион · мир','Профессиональный календарь · Россия · СНГ · Европа · Азия · Ближний Восток · Африка · Америка')
        s=s.replace('<span class="meta-chip">РФ, СНГ и Азия–Тихоокеанский регион</span>','<span class="meta-chip">Россия, СНГ и весь мир</span>')
        s=re.sub(r'<meta name="description" content="[^"]*">','<meta name="description" content="Мировой календарь офтальмологических конгрессов: Россия, СНГ, Китай, Азия, Ближний Восток, Европа, Африка и Америка — события, дедлайны и регистрация.">',s,count=1)
    else:
        s=s.replace('Professional calendar · Russia · CIS · Asia–Pacific · worldwide','Professional calendar · Russia · CIS · Europe · Asia · Middle East · Africa · Americas')
        s=s.replace('<span class="meta-chip">Russia, CIS and Asia–Pacific</span>','<span class="meta-chip">Russia, CIS and worldwide</span>')
        s=re.sub(r'<meta name="description" content="[^"]*">','<meta name="description" content="Global ophthalmology congress calendar covering Russia, CIS, China, Asia-Pacific, Middle East, Europe, Africa and the Americas — events, deadlines and registration.">',s,count=1)
    path.write_text(s,encoding='utf-8')

patch_page(ROOT/'for-doctors/events/index.html','ru')
patch_page(ROOT/'en/for-doctors/events/index.html','en')
print(f'Global events expansion applied: {len(EVENTS)} upserts; total={len(ru_ids)}')
